def shell_sort(lst):
    n = len(lst)
    gap = n // 2
    while gap > 0:
        for i in range(gap, n):
            temp = lst[i]
            j = i - gap
            while j >= 0 and temp < lst[j]:
                lst[j + gap] = lst[j]
                j -= gap
            lst[j + gap] = temp
        gap //= 2
    return lst

