def cocktail_shaker_sort(lst):
    n = len(lst)
    swapped = True
    while swapped:
        swapped = False
        for i in range(n-1):
            if lst[i] > lst[i+1]:
                lst[i], lst[i+1] = lst[i+1], lst[i]
                swapped = True
        if not swapped:
            break
        swapped = False
        for i in range(n-2, -1, -1):
            if lst[i] > lst[i+1]:
                lst[i], lst[i+1] = lst[i+1], lst[i]
                swapped = True
    return lst

