def matrix_neighbors(matrix):
    rows = len(matrix)
    cols = len(matrix[0])
    result = [[0] * cols for _ in range(rows)]

    for i in range(rows):
        for j in range(cols):
            if matrix[i][j] == 0:
                result[i][j] = 1
            elif matrix[i][j] < 0:
                result[i][j] = 0
            else:
                result[i][j] = matrix[i][j]

                # Check top neighbor
                if i > 0:
                    result[i][j] += matrix[i-1][j]

                # Check bottom neighbor
                if i < rows - 1:
                    result[i][j] += matrix[i+1][j]

                # Check left neighbor
                if j > 0:
                    result[i][j] += matrix[i][j-1]

                # Check right neighbor
                if j < cols - 1:
                    result[i][j] += matrix[i][j+1]

    return result

