def is_magic_square(matrix):
    n = len(matrix)
    if n != 3:
        return False

    # Calculate the sum of the first row
    total_sum = sum(matrix[0])

    # Check if all rows have the same sum
    for i in range(1, n):
        if sum(matrix[i]) != total_sum:
            return False

    # Check if all columns have the same sum
    for j in range(n):
        col_sum = sum(matrix[i][j] for i in range(n))
        if col_sum != total_sum:
            return False

    # Check if both diagonals have the same sum
    diag_sum1 = sum(matrix[i][i] for i in range(n))
    diag_sum2 = sum(matrix[i][n-i-1] for i in range(n))
    if diag_sum1 != total_sum or diag_sum2 != total_sum:
        return False

    return True

