from collections import defaultdict

def gardenNoAdj(n, paths):
    graph = defaultdict(set)
    for u, v in paths:
        graph[u-1].add(v-1)
        graph[v-1].add(u-1)

    result = [0]*n
    for node in range(n):
        used_flowers = set()
        for neighbor in graph[node]:
            used_flowers.add(result[neighbor])

        for flower in range(1,5):
            if flower not in used_flowers:
                result[node] = flower
                break

    return result

