def subsequence(seq, sub):
    if not sub:
        return True
    if len(sub) > len(seq):
        return False
    for i in range(len(seq)):
        if seq[i] == sub[0]:
            if subsequence(seq[i+1:], sub[1:]):
                return True
    return False

