def extended_geometric_mean_in_range(l: List[int], min_val: int, max_val: int) -> bool:
    if len(l) == 0 or any(x < 0 or x > 9 for x in l):
        return False

    product = 1
    for num in l:
        product *= num

    geometric_mean = round(product ** (1/len(l)), 6)

    return min_val <= geometric_mean <= max_val

