def find_longest_subarray_sum_equals_target(nums, target):
    prefix_sums = {0: -1}  # Initialize with prefix sum 0 at index -1
    max_length = 0
    current_sum = 0

    for i, num in enumerate(nums):
        current_sum += num

        if current_sum - target in prefix_sums:
            max_length = max(max_length, i - prefix_sums[current_sum - target])

        if current_sum not in prefix_sums:
            prefix_sums[current_sum] = i

    return max_length

